import json, os
OUT = "/tmp/claude-0/-home-user-gelato-paradiso/bccbadb1-94fa-50d4-9a03-5366ba381e06/scratchpad/bussola/linhas"

def E(data, tipo, titulo, texto, fonte, status=None, pessoas=None):
    return {"data": data, "tipo": tipo, "titulo": titulo, "texto": texto,
            "status": status, "pessoas": pessoas or [], "fonte": fonte}

def save(obj):
    obj["eventos"].sort(key=lambda e: e["data"])
    fontes = []
    for e in obj["eventos"]:
        if e["fonte"] not in fontes:
            fontes.append(e["fonte"])
    for f in obj.get("fontes_extra", []):
        if f not in fontes:
            fontes.append(f)
    obj.pop("fontes_extra", None)
    obj["fontes"] = fontes
    p = os.path.join(OUT, obj["id"] + ".json")
    with open(p, "w", encoding="utf-8") as fh:
        json.dump(obj, fh, ensure_ascii=False, indent=1)
    json.load(open(p, encoding="utf-8"))
    print(obj["id"], len(obj["eventos"]))

